<script setup lang="ts">import {ref,computed} from 'vue';import type {Workspace} from '../stores/workspace';import PageHeading from '../components/common/PageHeading.vue';import Notice from '../components/common/Notice.vue';import Status from '../components/common/Status.vue';import Empty from '../components/common/Empty.vue';import PhaseCompare from '../components/PhaseCompare.vue';import GraphView from '../components/GraphView.vue';import ShortestPanel from '../components/ShortestPanel.vue';import ArcFlowTable from '../components/ArcFlowTable.vue';import ConservationTable from '../components/ConservationTable.vue';import {PHASES} from '../constants/enums';const props=defineProps<{data:Workspace}>();const selected=ref(''),phase=ref<'baseline'|'outage'>('outage'),mode=ref('flow');const run=computed(()=>props.data.runs.find(r=>r.id===selected.value)||props.data.runs[0]);const current=computed(()=>run.value?.result?.[phase.value]);</script><template><PageHeading code="05 / FLOW & DETOUR EVIDENCE" title="最大流与最短路，分别给证据。" description="每条边保留独立正反残量，逐节点核对守恒；最短路径只在正容量启用边中计算。"/><div class="run-selector"><label>推演记录<select aria-label="选择推演记录" :value="run?.id" @change="selected=($event.target as HTMLSelectElement).value"><option v-for="r in data.runs" :key="r.id" :value="r.id">{{data.scenarios.find(s=>s.id===r.scenario_id)?.name}} · {{r.created_at.slice(11,19)}}</option></select></label><Status v-if="run" :value="run.status"/></div><Empty v-if="!run">保存源汇与停用边快照后，运行独立worker获取对照证据。</Empty><Notice v-else-if="run.status!=='completed'" :error="run.status==='failed'">{{run.status==='failed'?run.error:'后台正在计算容量、割集、守恒和最短时长，结果会自动刷新。'}}</Notice><template v-else-if="current"><PhaseCompare :result="run.result"/><div class="phase-selector"><div><button :class="{active:phase==='baseline'}" @click="phase='baseline'">基线网络</button><button :class="{active:phase==='outage'}" @click="phase='outage'">停用方案</button></div><div><button :class="{active:mode==='flow'}" @click="mode='flow'">最大流视图</button><button :class="{active:mode==='path'}" @click="mode='path'">独立最短路径视图</button></div></div><section class="paper"><div class="section-heading"><h2>网络边ID与流向证据</h2><span>{{PHASES[phase]}} / {{run.result.source}} → {{run.result.sink}} / 箱每小时与分钟分开</span></div><GraphView :nodes="run.result.nodes" :arcs="run.result.arcs" :flow="current.max_flow" :path="current.shortest" :disabled="phase==='outage'?run.result.disabled_arc_ids:[]" :mode="mode" :id-prefix="'result-'+phase"/></section><ShortestPanel :path="current.shortest"/><section class="paper"><h2>残量最小割证据</h2><div class="cut-evidence"><div><small>残量可达源侧</small><b>{{current.max_flow.source_side.join('、')}}</b></div><div><small>汇侧</small><b>{{current.max_flow.sink_side.join('、')}}</b></div><div><small>割容量 / 箱每小时</small><b>{{current.max_flow.cut_capacity}}</b></div></div><p class="caption">割边ID：{{current.max_flow.cut_arcs.map(a=>a.arc_id+'('+a.effective_capacity+')').join('、')||'无正容量割边'}}；括号为有效容量。停用/零容量边可跨割但贡献为0。</p><ArcFlowTable :flow="current.max_flow"/></section><section class="paper"><h2>逐节点流守恒</h2><ConservationTable :flow="current.max_flow"/><p class="caption">源节点流出−流入=最大流，汇为负最大流，其余节点为0；容量界与余额均按整数精确核验。</p></section><section class="paper"><h2>增广路径记录</h2><p class="caption">{{current.max_flow.augmentations.length}}次增广，{{current.max_flow.residual_edge_count}}条独立正/反残量边。预览前10次；负方向表示取消该原始边已有流量，不与另一条反向原始边混淆。</p><div class="table-scroll"><table><thead><tr><th>次序</th><th>增广量 / 箱每小时</th><th>残量步</th></tr></thead><tbody><tr v-for="(a,i) in current.max_flow.augmentations.slice(0,10)" :key="i"><td>{{i+1}}</td><td>{{a.amount}}</td><td>{{a.steps.map(s=>(s.direction===-1?'−':'+')+s.arc_id).join(' → ')}}</td></tr></tbody></table></div></section><aside class="assumptions"><h2>解释边界</h2><p v-for="(a,i) in run.result.assumptions" :key="a"><b>0{{i+1}}</b>{{a}}</p><small>锁定快照校验码 {{run.result.checksum.slice(0,24)}}</small></aside></template></template>
